alter table public.shops drop constraint shops_category_check;
alter table public.shops add constraint shops_category_check check(category in ('meal','dessert','gift','stay'));
alter table public.shops add column region text not null default 'nonsan', add column accommodation_type text;
insert into public.shops (shop_id,name,category,image_url,address,business_hours,phone,products,external_url,map_url,description,is_demo,region,accommodation_type) values ('nonsan-stay-01','MUSUBU 물빛쉼표 스테이','stay','assets/nearby-stay.svg','충청남도 논산시 · 가상 배치 위치','15:00 / 11:00','연락처 없음 · 가상 업체','[{"name": "호수 전망 펜션", "price": "요금 미정 · 데모"}]','demo-shop.html?shop=nonsan-stay-01&region=nonsan','https://www.google.com/maps/search/?api=1&query=36.184,127.165','탑정호 수변을 모티브로 한 호수 전망 숙소. 산책 후 조용히 쉬어가는 여행을 상상했습니다.',true,'nonsan','호수 전망 펜션') on conflict (shop_id) do nothing;
