create table public.shop_likes (
 shop_id text not null references public.shops(shop_id),
 visitor_hash text not null default encode(sha256(convert_to(current_setting('request.headers',true)::jsonb->>'x-musubu-visitor','UTF8')),'hex'),
 liked boolean not null default true, primary key(shop_id,visitor_hash)
);
alter table public.shop_likes enable row level security;
revoke all on public.shop_likes from anon,authenticated;
grant select on public.shop_likes to anon;
grant insert(shop_id,liked),update(liked) on public.shop_likes to anon;
create policy shop_likes_read on public.shop_likes for select to anon using(true);
create policy shop_likes_insert on public.shop_likes for insert to anon with check(visitor_hash=encode(sha256(convert_to(current_setting('request.headers',true)::jsonb->>'x-musubu-visitor','UTF8')),'hex') and char_length(visitor_hash)=64);
create policy shop_likes_update on public.shop_likes for update to anon using(visitor_hash=encode(sha256(convert_to(current_setting('request.headers',true)::jsonb->>'x-musubu-visitor','UTF8')),'hex')) with check(visitor_hash=encode(sha256(convert_to(current_setting('request.headers',true)::jsonb->>'x-musubu-visitor','UTF8')),'hex'));
